      --panel: #111827;
      --panel-light: #1f2937;
      --text: #e5e7eb;
      --muted: #94a3b8;
      --accent: #38bdf8;
      --accent-strong: #0ea5e9;
      --border: rgba(148, 163, 184, 0.22);
      --success: #22c55e;
      --danger: #f87171;
