      font-size: 1.12rem;
      font-weight: 800;
      margin-bottom: 0.4rem;
      padding: 0;
    }

    fieldset {
      border: 0;
      margin: 0;
      padding: 0;
    }

    .help-text {
      color: var(--muted);
      font-size: 0.95rem;
      line-height: 1.5;
      margin: 0 0 1rem;
    }

    .choices {
      display: grid;
      gap: 0.75rem;
      margin-top: 1rem;
    }

    label {
      align-items: center;
      background: rgba(15, 23, 42, 0.72);
      border: 1px solid transparent;
      border-radius: 14px;
      cursor: pointer;
      display: flex;
      gap: 0.75rem;
      padding: 0.9rem 1rem;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
