    button:focus-visible {
      transform: translateY(-2px);
      box-shadow: 0 20px 38px rgba(14, 165, 233, 0.36);
      outline: none;
    }

    .result {
      border-radius: 16px;
      color: var(--text);
      font-weight: 700;
      line-height: 1.5;
      margin-top: 1rem;
      min-height: 0;
      padding: 0;
    }

    .result:not(:empty) {
      background: rgba(34, 197, 94, 0.12);
      border: 1px solid rgba(34, 197, 94, 0.36);
      padding: 1rem;
    }

