      background: rgba(248, 113, 113, 0.12);
      border-color: rgba(248, 113, 113, 0.42);
    }
  </style>
</head>
<body>
  <main>
    <section class="quiz-card" aria-labelledby="quiz-title">
      <p class="eyebrow">Multiple answer quiz</p>
      <h1 id="quiz-title">Computer Languages</h1>
      <p class="intro">Choose every answer that applies for each question, then submit to see your score.</p>

      <form id="quiz-form">
        <div class="form-field">
          <fieldset>
            <legend>1. Which of these are commonly used programming languages?</legend>
            <p class="help-text">Select all languages used to write software; more than one answer is correct.</p>
            <div class="choices">
              <label><input type="checkbox" name="q1" value="javascript"> JavaScript</label>
              <label><input type="checkbox" name="q1" value="python"> Python</label>
              <label><input type="checkbox" name="q1" value="html"> HTML</label>
              <label><input type="checkbox" name="q1" value="ruby"> Ruby</label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>2. Which languages are typically compiled before execution?</legend>
            <div class="choices">
              <label><input type="checkbox" name="q2" value="c"> C</label>
              <label><input type="checkbox" name="q2" value="go"> Go</label>
              <label><input type="checkbox" name="q2" value="css"> CSS</label>
              <label><input type="checkbox" name="q2" value="rust"> Rust</label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>3. Which languages are often used for web development?</legend>
            <div class="choices">
              <label><input type="checkbox" name="q3" value="javascript"> JavaScript</label>
              <label><input type="checkbox" name="q3" value="php"> PHP</label>
              <label><input type="checkbox" name="q3" value="swift"> Swift</label>
              <label><input type="checkbox" name="q3" value="typescript"> TypeScript</label>
            </div>
          </fieldset>
        </div>

        <button type="submit">Submit answers</button>
        <div id="result" class="result" role="status" aria-live="polite"></div>
      </form>
    </section>
  </main>

  <script>
    const quizForm = document.querySelector("#quiz-form");
    const result = document.querySelector("#result");
    const answers = {
      q1: ["javascript", "python", "ruby"],
      q2: ["c", "go", "rust"],
      q3: ["javascript", "php", "typescript"]
    };

    function getSelectedValues(questionName) {
      return [...quizForm.querySelectorAll(`input[name="${questionName}"]:checked`)]
        .map((input) => input.value)
        .sort();
    }

    function arraysMatch(first, second) {
      return first.length === second.length && first.every((value, index) => value === second[index]);
    }

    quizForm.addEventListener("submit", (event) => {
      event.preventDefault();

      let score = 0;
      const total = Object.keys(answers).length;

      for (const [questionName, correctAnswers] of Object.entries(answers)) {
        if (arraysMatch(getSelectedValues(questionName), [...correctAnswers].sort())) {
          score += 1;
        }
      }

      result.classList.remove("error");
      result.textContent = `You scored ${score} out of ${total}.`;

      if (score < total) {
        result.classList.add("error");
      }
    });
  </script>
</body>
</html>
